<?php

namespace Database\Seeders;

use App\Models\PhaseContent;
use Illuminate\Database\Seeder;

/**
 * Seeds the phase_contents table with per-subphase educational content used by
 * the Phase Details screen. Each of the twelve CycleSubphase values gets nine
 * localized sections (symptom prediction, discharge, fertility, hormonal
 * changes, sex tips, nutrition, exercise, skin care and sleep). Content is
 * Persian-only for now (`en` is null) and is transcribed verbatim from the
 * product spec. The seeder is idempotent: re-running updates existing rows.
 */
class PhaseContentSeeder extends Seeder
{
    public function run(): void
    {
        foreach ($this->content() as $phase => $sections) {
            PhaseContent::updateOrCreate(['phase' => $phase], $sections);
        }
    }

    /**
     * Wrap Persian text as the bilingual section payload ({fa, en}).
     *
     * @return array{fa: string, en: null}
     */
    private function bi(string $fa): array
    {
        return ['fa' => $fa, 'en' => null];
    }

    /**
     * @return array<string, array<string, array{fa: string, en: null}>>
     */
    private function content(): array
    {
        return [
            'menstruation' => [
                'symptom_prediction' => $this->bi('شروع پریود معمولاً با افت انرژی و دردهای خفیف یا متوسط در ناحیه زیر شکم و کمر همراه است. طبیعی است که در این روزها حس کنی نیاز به استراحت بیشتری داری؛ بدن تو در حال انجام یک فعالیت بیولوژیک مهم است. اگر دردها تا حدی است که زندگی عادی‌ات را مختل کرده، نگران نباش اما حتماً به آن توجه کن.'),
                'vaginal_discharge' => $this->bi('در این روزها خون‌ریزی تنها چیزی است که می‌بینی. ترشحات واژینال طبیعی در حضور خون پوشانده می‌شوند، بنابراین تمرکزت فقط روی رنگ و قوام خون باشد. خون روشن و روان در ابتدای پریود کاملاً طبیعی است.'),
                'fertility' => $this->bi('در این فاز، شانس باروری در پایین‌ترین حد خود قرار دارد. اگرچه اسپرم می‌تواند چند روز زنده بماند، اما در این فاز احتمال تخمک‌گذاری بسیار نزدیک به صفر است.'),
                'hormonal_changes' => $this->bi('سطح هورمون‌های زنانه (استروژن و پروژسترون) در پایین‌ترین سطح قرار دارند. این افت هورمونی دلیل اصلی خستگی و تغییرات خلقی است که شاید حس می‌کنی.'),
                'sex_tips' => $this->bi('رابطه در این دوران کاملاً شخصی است. برخی افراد به دلیل احتقان لگن میل جنسی بیشتری دارند و برخی کاملاً بی‌میل‌اند. هر دو حالت نرمال است؛ مهم‌ترین اصل، رعایت بهداشت و راحتی توست.'),
                'nutrition' => $this->bi('جایگزینی آهن از دست رفته با غذاهایی مثل گوشت قرمز، حبوبات یا اسفناج عالی است. همچنین مصرف گرمی‌جات می‌تواند به کاهش گرفتگی‌های عضلانی (کرامپ) کمک کند.'),
                'exercise' => $this->bi('گوش دادن به بدنت مهم‌ترین اصل است. اگر حس می‌کنی توان نداری، ورزش را به پیاده‌روی‌های سبک یا یوگای ترمیمی محدود کن. فشار زیاد در این روزها نتیجه معکوس دارد.'),
                'skin_care' => $this->bi('به دلیل افت هورمون‌ها، پوست ممکن است کمی خشک یا کدر به نظر برسد. از یک مرطوب‌کننده ملایم استفاده کن و روتین‌های سنگین لایه‌برداری را برای هفته بعد بگذار.'),
                'sleep' => $this->bi('خواب ممکن است به دلیل درد یا ناراحتی فیزیکی کمی سخت شود. استفاده از کیسه آب گرم و موقعیت خوابی که فشار را از روی کمر بردارد، کیفیت استراحتت را بالا می‌برد.'),
            ],

            'early_follicular' => [
                'symptom_prediction' => $this->bi('پریود تمام شده و حس می‌کنی باری از دوشت برداشته شده. انرژی در حال بازگشت است و شفافیت ذهنی‌ات نسبت به هفته قبل بهبود چشمگیری پیدا کرده. این یعنی بدنت آماده شروع چرخه جدید است.'),
                'vaginal_discharge' => $this->bi('ترشحات هنوز بسیار کم هستند، شاید حتی احساس خشکی داشته باشی. این حالت کاملاً طبیعی است و نشان می‌دهد بدن هنوز در حال “شروعِ” تولید استروژن است.'),
                'fertility' => $this->bi('هنوز در فاز غیرباروری هستی، اما با پایان یافتن پریود، پنجره امن چرخه به آرامی در حال تغییر است. برای کسانی که سیکل کوتاهی دارند، احتیاط از همین الان شروع می‌شود.'),
                'hormonal_changes' => $this->bi('سطح استروژن به آرامی در حال افزایش است. این هورمون مثل بنزین برای موتور بدنت عمل می‌کند و به تدریج خلق‌وخوی تو را مثبت‌تر می‌کند.'),
                'sex_tips' => $this->bi('با بهبود خلق‌وخو، میل جنسی کم‌کم بیدار می‌شود. این زمان عالی برای اتصال دوباره به خودت و شریک زندگی‌ات است، بدون فشارهای هورمونیِ فازهای بعدی.'),
                'nutrition' => $this->bi('بهترین زمان برای تنظیم رژیم غذایی. بدن الان پذیرای غذاهای غنی از ویتامین و پروتئین است تا ذخایر تخلیه شده در پریود را بازیابی کند.'),
                'exercise' => $this->bi('سطح انرژی رو به افزایش است. الان زمان خوبی برای شروع تمرینات هوازی (مثل دویدن سبک یا شنا) است تا سیستم قلبی-عروقی‌ات دوباره فعال شود.'),
                'skin_care' => $this->bi('پوست الان آماده جذب مواد مغذی است. اگر قصد داری روتین پوستی جدید یا کرم خاصی را تست کنی، این روزها بهترین زمان است چون پوست حساسیت کمتری دارد.'),
                'sleep' => $this->bi('کیفیت خواب در این روزها معمولاً بسیار پایدار است. چون هنوز دمای بدن پایین است، خواب عمیق راحت‌تر اتفاق می‌افتد.'),
            ],

            'mid_follicular' => [
                'symptom_prediction' => $this->bi('این فازِ “سوپرمن” توست! بسیاری از زنان در این دوران بیشترین تمرکز ذهنی و توان حل مسئله را دارند. حس سبکی و اعتماد به نفس بالاتری داری و ارتباطات اجتماعی‌ات روان‌تر پیش می‌رود.'),
                'vaginal_discharge' => $this->bi('ترشحات شروع به تغییر قوام می‌کنند. ممکن است حس کنی ترشحات کمی کرمی یا غلیظ‌تر شده‌اند. این یعنی کارخانه‌ی هورمونی بدنت به خوبی در حال فعالیت است.'),
                'fertility' => $this->bi('احتمال باروری کم‌کم به سمت متوسط می‌رود. اگر قصد بارداری نداری، حتماً مراقب باش، چون اسپرم می‌تواند در این محیطِ در حال تغییر، زنده بماند.'),
                'hormonal_changes' => $this->bi('استروژن با سرعت در حال صعود است. این هورمون علاوه بر سلامت باروری، روی سیستم عصبی‌ات اثر گذاشته و باعث می‌شود اضطراب کمتری داشته باشی.'),
                'sex_tips' => $this->bi('با افزایش استروژن، حساسیت فیزیکی بدنت بالاتر رفته و لذت بردن راحت‌تر است. بدن تو در حال آماده‌سازی برای روزهای پرشور آینده است.'),
                'nutrition' => $this->bi('مصرف فیبر و سبزیجات برگ‌سبز به بدن کمک می‌کند تا استروژن‌های اضافی را مدیریت کند. این کار از نفخ‌های احتمالی در آینده جلوگیری می‌کند.'),
                'exercise' => $this->bi('توان استقامتی‌ات عالی است. اگر به دنبال ثبت رکورد شخصی در ورزش هستی یا می‌خواهی تمرینات قدرتی سنگین‌تری انجام دهی، الان دقیقاً وقتش است.'),
                'skin_care' => $this->bi('به دلیل درخشش طبیعی که استروژن به پوست می‌دهد، نیاز به آرایش سنگین نداری. پوستت الان در یکی از بهترین حالت‌های خودش است.'),
                'sleep' => $this->bi('خوابت در این فاز بسیار باکیفیت است. چون دمای مرکزی بدنت هنوز پایین است، راحت‌تر به خواب عمیق می‌روی و صبح‌ها با انرژی بیشتری بیدار می‌شوی.'),
            ],

            'fertile_rising' => [
                'symptom_prediction' => $this->bi('در این روزها ممکن است حس کنی انرژی‌ات بیشتر شده، تمرکزت بهتر است و حتی خلق‌وخویت نسبت به چند روز قبل سبک‌تر و بازتر شده. خیلی از افراد در این فاز احساس اجتماعی‌تر بودن، میل بیشتر به حرکت، برنامه‌ریزی یا ارتباط با دیگران را تجربه می‌کنند. این تغییرات معمولاً به دلیل بالا رفتن تدریجی استروژن اتفاق می‌افتد.'."\n\n".'ممکن است هنوز علامت واضحی از تخمک‌گذاری نداشته باشی، اما بدن آرام‌آرام وارد مرحله‌ای می‌شود که برای باروری آماده‌تر است. اگر در این روزها درد خفیف لگنی، حساسیت سینه یا تغییرات ملایم در میل جنسی را حس کردی، معمولاً می‌تواند بخشی از روند طبیعی چرخه باشد.'),
                'vaginal_discharge' => $this->bi('ترشحات واژینال در این فاز معمولاً از حالت خشک یا چسبنده، به سمت شفاف‌تر، مرطوب‌تر و لغزنده‌تر شدن می‌روند. ممکن است هنوز کاملاً کشسان یا شبیه سفیده تخم‌مرغ نباشند، اما تغییر در رطوبت و قوام ترشحات یکی از نشانه‌های مهم ورود بدن به پنجره باروری است.'."\n\n".'این تغییر به دلیل افزایش استروژن اتفاق می‌افتد. بدن با ایجاد ترشحات بارورتر، محیط واژن و دهانه رحم را برای زنده ماندن و حرکت بهتر اسپرم آماده می‌کند. اگر ترشحات همراه با خارش، سوزش، درد یا بوی تند غیرمعمول نباشند، این تغییرات معمولاً طبیعی و قابل انتظار هستند.'),
                'fertility' => $this->bi('در این فاز احتمال باروری از سطح پایین به سمت متوسط افزایش پیدا می‌کند. هنوز معمولاً در اوج باروری نیستی، اما بدن وارد بازه‌ای شده که رابطه جنسی می‌تواند از نظر باروری اهمیت بیشتری پیدا کند؛ چون اسپرم در شرایط مناسب می‌تواند چند روز در بدن زنده بماند و منتظر تخمک‌گذاری بماند.'."\n\n".'اگر در حال اقدام برای بارداری هستی، این روزها شروع خوبی برای برنامه‌ریزی رابطه در بازه باروری هستند. اگر قصد بارداری نداری، بهتر است از همین مرحله پیشگیری را جدی‌تر بگیری، چون اتکا به «هنوز روز تخمک‌گذاری نرسیده» روش قابل اعتمادی برای پیشگیری نیست.'),
